
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_sogga11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_sogga11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.257058525684716e+00, -4.174835702920558e+00, -4.059694330652831e+00, -3.900334480769928e+00, -3.683433681175423e+00, -3.395096638572490e+00, -3.023946170288645e+00, -2.564958684422012e+00, -2.018640087246783e+00, -1.411711809029940e+00, -9.809021384987231e-01, -6.862203225511996e-01, -5.975846488682285e-01, -4.910564271846388e-01, -3.449076811865219e-01, -1.774708545816198e-01, 2.532382583896171e-02, -2.481403272027935e-01, -8.794600904234841e-02, -1.010935823498089e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


